import{_ as n,C as r,o as s,c as i,a2 as t,E as o}from"./chunks/framework.9yf7n3zg.js";const d="/guide/media/beat-board-overview.webp",h="/guide/media/beat-board-card-side.webp",c="/guide/media/beat-board-own-column.webp",y=JSON.parse('{"title":"Beat board","description":"","frontmatter":{},"headers":[],"relativePath":"guide/beat-board.md","filePath":"guide/beat-board.md","lastUpdated":1791677002000}'),l={name:"guide/beat-board.md"};function g(u,e,p,m,b,f){const a=r("Clip");return s(),i("div",null,[e[0]||(e[0]=t('<h1 id="beat-board" tabindex="-1">Beat board <a class="header-anchor" href="#beat-board" aria-label="Permalink to &quot;Beat board&quot;">​</a></h1><p>The beat board is where a story is first explored, before there is a grid to fill. It lays out the beats of a structure (Three acts, Save the Cat, the Hero&#39;s journey, Kishōtenketsu, or a template of your own) as columns grouped by act, and you put cards in them freely. A card is a short markdown note Leathercase keeps for you; nothing on the board is prose, and the board never opens your manuscript files. When a card is ready, you can send it on to the <a href="/guide/guide/plot-grid">plot grid</a> as a planned scene.</p><p><img src="'+d+'" alt="The beat board of The Lamp at Ferrol on the Three acts template: the state line, the Loose column with A light that lies, then Act I with Opening, Inciting incident holding The lamp goes dark, and First turn" width="1130" height="401" loading="lazy"></p><h2 id="opening-the-board" tabindex="-1">Opening the board <a class="header-anchor" href="#opening-the-board" aria-label="Permalink to &quot;Opening the board&quot;">​</a></h2><p>Open a story, then pick <strong>Beat board</strong> under the story&#39;s name in the sidebar. It is the first of the story&#39;s views. You can also press <code>Ctrl+9</code> (<code>Cmd+9</code> on macOS), or type &quot;Beat board&quot; in the command palette (<code>Ctrl/Cmd+K</code>).</p><p>While the cards are read from disk the board says <strong>Reading the beat board…</strong>. The board reads its cards again every time the Leathercase window comes back to the front, so a card you captured over another app, or a card note you changed in your own editor, shows as soon as you return.</p><h2 id="what-the-board-shows" tabindex="-1">What the board shows <a class="header-anchor" href="#what-the-board-shows" aria-label="Permalink to &quot;What the board shows&quot;">​</a></h2><p>The board runs left to right:</p><table tabindex="0"><thead><tr><th>Part</th><th>What it is</th></tr></thead><tbody><tr><td><strong>Not placed</strong></td><td>The first group, holding one column, <strong>Loose</strong>. Its line reads &quot;Cards with no beat yet, and those whose beat this template does not have.&quot;</td></tr><tr><td>An act</td><td>A heading with the act&#39;s name (<strong>Act I</strong>, <strong>Act II</strong>, <strong>Act III</strong> for Three acts; <strong>Ki: introduction</strong> and so on for Kishōtenketsu), and under it a column for each of its beats.</td></tr><tr><td>A column</td><td>The beat&#39;s name, the number of cards in it, and a line under the head saying what happens at that beat, taken from the template (for <strong>Midpoint</strong>: &quot;A false win or a false loss that changes what the hero wants&quot;). A column you added yourself is marked <strong>yours</strong> and has no such line.</td></tr><tr><td>A card</td><td>Its title, the first lines of its text (point at them to read it whole), its tags as coloured chips, and small marks when they apply: <strong>beat: Crisis</strong> on a loose card that keeps a beat the template lacks, and <strong>on the grid</strong> on a card already sent to the grid.</td></tr></tbody></table><p>The line at the top of the view is the board&#39;s state: how many cards it holds, how many are loose, and the template in force, for example <code>4 cards · 1 loose · Three acts</code>. On an empty board it reads <code>no cards yet · none loose · Three acts</code>.</p><p>The footer names the keys the board answers to; press <code>?</code> to see them in a small panel and <code>Esc</code> to put it away. The side column on the right holds what you can do with the card or column in hand, and the <strong>About</strong> section. Toggle it with the side column button at the right of the head, or <code>Ctrl/Cmd+B</code>.</p><p>Tag chips take the colour you gave the tag in the <a href="/guide/guide/tags">Tags</a> view.</p><h2 id="making-a-card" tabindex="-1">Making a card <a class="header-anchor" href="#making-a-card" aria-label="Permalink to &quot;Making a card&quot;">​</a></h2><p>Every column, <strong>Loose</strong> included, has <strong>+ a card</strong> at its foot. Click it, or press <code>N</code> on the board: with a card picked, <code>N</code> opens the form in that card&#39;s column; with a column picked, in that column; otherwise in <strong>Loose</strong>.</p><p>The form is one field, typed as markdown:</p><ul><li>The first line is the card&#39;s title. It may start with <code>#</code> as a heading or not.</li><li><code>Enter</code> on a one-line draft makes the card at once.</li><li><code>Shift+Enter</code> starts a new line; everything after the first line is the card&#39;s text. With more than one line, <code>Ctrl/Cmd+Enter</code> makes the card.</li><li>A <code>#tag</code> anywhere in the title or the text becomes a tag. It leaves the text and shows as a chip. <code>#place/coast</code> works too.</li><li><code>Esc</code> or <strong>Cancel</strong> closes the form without making anything.</li></ul><p>The button reads <strong>Add</strong> until there is a title, then <strong>Add &quot;…&quot;</strong> with the start of it. The line under the form repeats the keys: &quot;enter adds · shift+enter for the text · a #tag becomes a tag&quot;.</p>',17)),o(a,{name:"beat-board-make-card",caption:"Making the card Lamp #mystery in Midpoint: the tag leaves the title and shows as a chip"}),e[1]||(e[1]=t(`<p>The card lands at the foot of the column. If a card of the same title already exists, the new one gets a number (<code>Storm 2</code>), so no card is ever written over.</p><h2 id="where-cards-live" tabindex="-1">Where cards live <a class="header-anchor" href="#where-cards-live" aria-label="Permalink to &quot;Where cards live&quot;">​</a></h2><p>Each card is a markdown note in the story&#39;s author data folder, under <code>Beats/</code>, named after its title. For The Lamp at Ferrol that is <code>The Lamp at Ferrol/suite/Beats/</code>. The <strong>About</strong> section of the side column prints the exact folder. A card made in <strong>Midpoint</strong> with the tag <code>mystery</code> reads:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">beat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Midpoint</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">created</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2026-10-06</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mystery</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Nora finds the lamp lit when it should be dark.</span></span></code></pre></div><p>The note says everything without Leathercase: its beat, its tags, the day it was made, and its text as the body. A card with no <code>beat:</code> line is loose. Characters a file name cannot hold (<code>/ \\ : * ? &quot; &lt; &gt; | # ^ [ ]</code>) become spaces in the file name.</p><p>The board keeps one file of its own, <code>BeatBoard.json</code> in the story&#39;s <code>suite/</code> folder. It records the template you chose, the columns you added and the order of the cards in each column. Delete it and the cards stay where their notes say; only your columns and the order are lost.</p><p>See <a href="/guide/reference/suite-files">Files Leathercase writes</a> for every file in the story&#39;s <code>suite/</code> folder.</p><h2 id="moving-a-card" tabindex="-1">Moving a card <a class="header-anchor" href="#moving-a-card" aria-label="Permalink to &quot;Moving a card&quot;">​</a></h2><p>Drag a card onto another column and drop it where you want it among the cards there. The card&#39;s note has its <code>beat:</code> line rewritten to the new column&#39;s name; nothing else in it changes. Drop it on <strong>Loose</strong> and the line is taken out.</p>`,9)),o(a,{name:"beat-board-drag",caption:"Dragging Storm from Crisis to Climax; the strip says Moved Storm to Climax"}),e[2]||(e[2]=t('<p>Dragging within a column reorders it. The order is kept in <code>BeatBoard.json</code>, not in the notes. A card that is not in the kept order yet (one you made in your own editor, say) comes after the ordered ones, oldest first.</p><p>You can also move a card from the side column with its <strong>Beat</strong> list; see below.</p><p>A loose card that keeps a beat the current template lacks stays as it is when you only reorder it among the loose cards: the board never rewrites a beat it did not move.</p><h2 id="picking-a-card" tabindex="-1">Picking a card <a class="header-anchor" href="#picking-a-card" aria-label="Permalink to &quot;Picking a card&quot;">​</a></h2><p>Click a card to pick it, or walk the cards with the left and right arrow keys, loose cards first, then column by column. <code>Esc</code> puts the selection away. The side column then shows a <strong>Selected</strong> section headed with the card&#39;s title, the path of its note, and these controls:</p><p><img src="'+h+'" alt="The side column with the card Kell&#39;s offer picked: its text, its tags, the Beat list, Put on the plot grid and Delete the card" width="359" height="701" loading="lazy"></p><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td>The text field</td><td>The card&#39;s text. Press <code>Enter</code> on the board to put the caret here. It is saved when you leave the field or press <code>Ctrl/Cmd+Enter</code>, and saved too if you switch view while typing. A <code>#tag</code> typed here becomes a tag.</td></tr><tr><td><strong>Tags</strong></td><td>The card&#39;s tags as chips; the <code>×</code> on a chip takes that tag off. The field below (&quot;a tag, new or known&quot;) suggests tags already used on the board; <strong>+ a tag</strong> puts the typed one on. A leading <code>#</code> is dropped. With no tags the row says <strong>none</strong>.</td></tr><tr><td><strong>Beat</strong></td><td>Every column of the board, with <strong>loose</strong> first. Choosing one moves the card to the foot of that column; &quot;moving the card rewrites the beat line in its note&quot;. For a loose card that keeps a beat the template lacks, the first choice reads &quot;Crisis, not on this template&quot;.</td></tr><tr><td><strong>Put on the plot grid</strong></td><td>Sends the card to the plot grid as a planned scene. See <a href="#from-card-to-scene">From card to scene</a>.</td></tr><tr><td><strong>Delete the card</strong></td><td>Deletes the card. See <a href="#deleting-a-card">Deleting a card</a>.</td></tr><tr><td><strong>close</strong></td><td>Puts the selection away.</td></tr></tbody></table>',7)),o(a,{name:"beat-board-tag-in-text",caption:"Writing The lamp goes out. #grief into Storm's text: the tag leaves the text and becomes a chip"}),e[3]||(e[3]=t('<h2 id="your-own-columns" tabindex="-1">Your own columns <a class="header-anchor" href="#your-own-columns" aria-label="Permalink to &quot;Your own columns&quot;">​</a></h2><p>The template&#39;s beats always stay on the board. Between them you can put columns of your own, an &quot;Aftermath&quot; after the climax, say.</p><ul><li>To add one after a column, click that column&#39;s head. The side column shows the column; type a name in the field (&quot;a column of your own&quot;) and click <strong>+ a column after</strong>.</li><li>To add one before every beat, use the field in the <strong>About</strong> section and click <strong>+ a column first</strong>.</li></ul><p>A new column sits in the act of the column it follows. With <strong>Aftermath</strong> added after <strong>Climax</strong>, Act III reads Climax, Aftermath, Falling action, Resolution. Two columns cannot share a name; the board refuses the second.</p><p>Click the head of one of your columns and the side column says <strong>a column of yours</strong>, with two more controls:</p><ul><li><strong>Rename</strong>: type the new name and click <strong>Rename</strong>. Every card in the column has its <code>beat:</code> line rewritten to the new name.</li><li><strong>Take the column off</strong>: the column goes, and &quot;its cards become loose and their notes lose the beat&quot;. Columns that followed it now follow what it followed.</li></ul><p>Click the head of a template&#39;s beat and the side column says, for example, &quot;a beat of Three acts; it stays on the board&quot;, with the act&#39;s name and the beat&#39;s line. It can be the place you add a column after, and it can be sent to the plot grid whole, but it cannot be renamed or taken off.</p><p><img src="'+c+'" alt="A column of yours picked: Aftermath after Climax, with Rename, Take the column off and Send the column to the plot grid" width="1035" height="389" loading="lazy"></p><h2 id="choosing-a-template" tabindex="-1">Choosing a template <a class="header-anchor" href="#choosing-a-template" aria-label="Permalink to &quot;Choosing a template&quot;">​</a></h2><p>Open the board&#39;s <code>⋯</code> menu (<strong>Beat board menu</strong>). Under the heading <strong>Template</strong> it lists every template that has beats, the one in force in the accent colour:</p><table tabindex="0"><thead><tr><th>Template</th><th>Acts and beats</th></tr></thead><tbody><tr><td><strong>Three acts</strong> (the default)</td><td>Act I: Opening, Inciting incident, First turn. Act II: Rising action, Midpoint, Crisis. Act III: Climax, Falling action, Resolution.</td></tr><tr><td><strong>Save the Cat</strong></td><td>Act I: Opening image, Theme stated, Set-up, Catalyst, Debate, Break into two. Act II: B story, Fun and games, Midpoint, Bad guys close in, All is lost, Dark night of the soul, Break into three. Act III: Finale, Final image.</td></tr><tr><td><strong>Hero&#39;s journey</strong></td><td>Departure: Ordinary world, Call to adventure, Refusal of the call, Meeting the mentor, Crossing the threshold. Initiation: Tests, allies, enemies; Approach to the inmost cave; Ordeal; Reward. Return: The road back, Resurrection, Return with the elixir.</td></tr><tr><td><strong>Kishōtenketsu</strong></td><td>Four acts, Ki: introduction, Shō: development, Ten: twist and Ketsu: reconciliation, with one beat each: Introduction, Development, Twist, Reconciliation.</td></tr><tr><td>Your own</td><td>Any template you saved from the grid that has beats. See <a href="/guide/guide/plot-grid#templates">Plot grid, templates</a>.</td></tr></tbody></table><p>The two built-in templates without beats, <strong>An arc per character</strong> and <strong>Story analysis</strong>, are grid templates only and do not appear here.</p><p>Picking another template lays the columns out from it. Your own columns stay, each after the column it followed; one whose column the new template lacks goes at the end. A card whose beat the new template lacks moves to <strong>Loose</strong> with a mark naming its beat (<strong>beat: Crisis</strong>), and its note keeps the line. Pick the first template again and the card goes back to its column. Changing template never rewrites a card.</p>',13)),o(a,{name:"beat-board-template",caption:"Choosing Kishōtenketsu from the ⋯ menu: the columns change and the cards wait in Loose, each marked with its beat; then Three acts again"}),e[4]||(e[4]=t('<h2 id="the-story-s-language" tabindex="-1">The story&#39;s language <a class="header-anchor" href="#the-story-s-language" aria-label="Permalink to &quot;The story&#39;s language&quot;">​</a></h2><p>A template&#39;s beats are words in the story&#39;s language, set in <a href="/guide/guide/story-settings">Story settings</a>. In a story declared in Português (Brasil), Three acts reads Ato I: Abertura, Incidente incitante, Primeira virada, and a card made there says <code>beat: Abertura</code>. An open board follows when you change the story&#39;s language.</p><p>Cards are matched to columns by name. A card whose beat is in another language than the template in force (one written before the story&#39;s language changed, or copied from another story) waits in <strong>Loose</strong>, marked with its beat, until a column of that name exists.</p><h2 id="deleting-a-card" tabindex="-1">Deleting a card <a class="header-anchor" href="#deleting-a-card" aria-label="Permalink to &quot;Deleting a card&quot;">​</a></h2><p>Two ways:</p><ul><li>Pick the card and press <code>Delete</code> (or <code>Backspace</code>). It goes at once, and the strip offers <strong>Undo</strong>.</li><li>In the side column click <strong>Delete the card</strong>. The button turns into <strong>Click again to delete</strong>; a second click deletes, and <strong>Keep</strong> disarms it.</li></ul><p>The note goes to the system&#39;s trash, not straight off the disk, and <code>Ctrl/Cmd+Z</code> brings it back.</p><h2 id="undo-and-the-strip" tabindex="-1">Undo and the strip <a class="header-anchor" href="#undo-and-the-strip" aria-label="Permalink to &quot;Undo and the strip&quot;">​</a></h2><p>Under the board runs a strip. Before anything is written it says &quot;Pick a card and press Enter to write in it.&quot; After each change it names what was written, such as <strong>Moved Storm to Climax</strong>, <strong>Made the card Lamp</strong>, <strong>Put #grief on Storm</strong>, <strong>Wrote in Storm</strong>, <strong>Added the column Aftermath</strong> or <strong>Laid the columns out from Kishōtenketsu</strong>, with <strong>Undo</strong> beside it and how many steps are in the stack. <strong>Redo</strong> appears once something has been undone.</p><p><code>Ctrl/Cmd+Z</code> undoes and <code>Ctrl/Cmd+Shift+Z</code> redoes, whenever the caret is not in a text field (inside a field they are the field&#39;s own). Undo puts back exactly what the change wrote: the card notes, <code>BeatBoard.json</code>, and the grid file when a card was sent to it. If a file was changed outside Leathercase since, undo writes nothing and the strip says &quot;The file changed outside Leathercase since; nothing was written, and the step was dropped.&quot; Your edit is never wiped.</p><p>The stack lives as long as the board is open.</p><h2 id="from-card-to-scene" tabindex="-1">From card to scene <a class="header-anchor" href="#from-card-to-scene" aria-label="Permalink to &quot;From card to scene&quot;">​</a></h2><p>When a card is ready to be a scene, pick it and click <strong>Put on the plot grid</strong>. The card becomes a planned scene in the story&#39;s grid file, <code>PlotGrid.md</code> in the story&#39;s <code>suite/</code> folder:</p><ul><li>It goes under its beat&#39;s act, after the last scene that carries the same beat. If no scene carries it yet, it goes at the end of the act, and the act is made if the grid lacks it. Acts are matched by name: in the sample, whose acts are called Act I - The Dark Lamp and so on, a card from Climax lands under a new act named <strong>Act III</strong>, in a group headed <strong>No chapter yet</strong>.</li><li>The card&#39;s title becomes the scene&#39;s title, its text the scene&#39;s summary, and the scene carries the beat.</li><li>The card stays on the board, marked <strong>on the grid</strong>, and its note gains a line <code>outline: &quot;[[PlotGrid#Storm]]&quot;</code>. The side column then reads &quot;on the plot grid as [[PlotGrid#Storm]]; putting it there again writes nothing&quot;.</li></ul><p>From then on the scene is yours to work on in the <a href="/guide/guide/plot-grid">plot grid</a>, where it shows as a planned row. The card and the scene are not kept in step: editing one does not change the other.</p><p>A loose card cannot be sent; the button is greyed and says &quot;A loose card has no beat to go under; put it in a column first.&quot; A card sent twice is written once, and the strip says &quot;Storm is already on the plot grid; nothing was written&quot;.</p><p>To send a whole column, click its head and then <strong>Send the column to the plot grid</strong>. Each card becomes a planned scene in the column&#39;s order; &quot;a card already there is left as it is&quot;, and the strip counts how many were. On an empty column the button is greyed and says &quot;no cards to send&quot;. For a column of your own, its scenes go after the scenes of the columns before it, back to the template&#39;s beat it follows.</p>',17)),o(a,{name:"beat-board-send",caption:"Putting The storm at the Point on the plot grid, then opening the plot grid to see it as a planned scene under Act III"}),e[5]||(e[5]=t('<p>Undo takes the scene out of the grid file and the <code>outline:</code> line out of the card.</p><h2 id="capturing-a-card-from-anywhere" tabindex="-1">Capturing a card from anywhere <a class="header-anchor" href="#capturing-a-card-from-anywhere" aria-label="Permalink to &quot;Capturing a card from anywhere&quot;">​</a></h2><p>The capture window (see <a href="/guide/guide/writer-board">The Writer Board</a>) can send a line straight to a story&#39;s beat board. In its <strong>To</strong> list choose &quot;Loose on The Lamp at Ferrol&#39;s beat board&quot;; the card lands in <strong>Loose</strong>, and the next capture starts on the same board.</p><h2 id="proposals-from-agents" tabindex="-1">Proposals from agents <a class="header-anchor" href="#proposals-from-agents" aria-label="Permalink to &quot;Proposals from agents&quot;">​</a></h2><p>An agent you connected with <strong>Lay out</strong> can propose new cards, moves and the board&#39;s template. They show in the proposal style beside your own cards while the assistant&#39;s layer is on (<code>Ctrl/Cmd+.</code>). Nothing is written until you accept. <strong>Review in Beat board</strong>, on a changeset in the inbox, opens the board with a review bar beside it, so you judge each proposal where it would land. See <a href="/guide/guide/inbox#reviewing-in-a-view">Proposals and the inbox</a>.</p><h2 id="keys" tabindex="-1">Keys <a class="header-anchor" href="#keys" aria-label="Permalink to &quot;Keys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>←</code> <code>→</code></td><td>Pick the previous or next card</td></tr><tr><td><code>Enter</code></td><td>Write in the picked card (puts the caret in its text)</td></tr><tr><td><code>N</code></td><td>New card in the picked card&#39;s column, the picked column, or Loose</td></tr><tr><td><code>Delete</code></td><td>Delete the picked card</td></tr><tr><td><code>Ctrl/Cmd+Z</code></td><td>Undo</td></tr><tr><td><code>Ctrl/Cmd+Shift+Z</code></td><td>Redo</td></tr><tr><td><code>Esc</code></td><td>Deselect</td></tr><tr><td><code>?</code></td><td>Show the keys</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/plot-grid">Plot grid</a>, where a card sent from the board becomes a planned scene</li><li><a href="/guide/guide/tags">Tags</a>, for the colours of the chips</li><li><a href="/guide/guide/writer-board">The Writer Board</a>, for cards that belong to no story yet</li><li><a href="/guide/reference/suite-files">Files Leathercase writes</a></li></ul>',9))])}const k=n(l,[["render",g]]);export{y as __pageData,k as default};
